int WeightPairFrequency::getWeightForLetter(char c, const std::string& word, unsigned int targetLength) {
	if (word.length() == 0) { return 0; }
	char lastChar = word.back();
	unsigned int row = (unsigned int)(lastChar - 'a');
	assertm(row >= 0 && row < 26, "Row is out of bounds!");
	unsigned int col = (unsigned int)(c - 'a');
	assertm(col >= 0 && col < 26, "Col is out of bounds!");
	return letterPairTable[(row * 26) + col];
}
